import type { FastifyInstance } from 'fastify'

export default async function (app: FastifyInstance) {
  // GET /api/tags — 인증 불필요. 모든 태그 이름을 문자열 배열로 반환.
  app.get('/tags', async () => {
    const tags = await app.prisma.tag.findMany()
    return { tags: tags.map((t) => t.name) }
  })
}

