import { afterAll, beforeAll, expect, test } from 'vitest'
import type { FastifyInstance } from 'fastify'
import { buildTestApp } from './helpers/app.js'

let app: FastifyInstance
let created: string[]

beforeAll(async () => {
  app = await buildTestApp()
  const n = Date.now()
  created = [`reactjs-${n}`, `angularjs-${n}`, `dragons-${n}`]
  await app.prisma.tag.createMany({
    data: created.map((name) => ({ name })),
    skipDuplicates: true,
  })
})
afterAll(async () => { await app.close() })

test('GET /api/tags → 200 with tags string array', async () => {
  const res = await app.inject({ method: 'GET', url: '/api/tags' })
  expect(res.statusCode).toBe(200)
  const body = res.json()
  // 응답 형태는 { tags: string[] }
  expect(Array.isArray(body.tags)).toBe(true)
  expect(body.tags.every((t: unknown) => typeof t === 'string')).toBe(true)
  // 이 테스트가 생성한 태그가 모두 포함되어야 한다
  for (const name of created) {
    expect(body.tags).toContain(name)
  }
})
